INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11942-math225', 'stk-user11942', 'MATH 225', 'doc', '{"docs": [{"id": "stk-dr-m68372", "n": "Dr. Hattan Tawfiq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math225-191\n\nطريقة الشرح/ يستخدم الكتاب والسبورة وفي حصص الماتلاب نروح معامل مبنى 5 وطريقته أنه يطبق المسألة ثم يطلب منا نعيدها بعدين يعطينا شيء مشابهة.\n\nإضافات /\n\n١- أخلاقه عالية والتعامل معه جميل\n\n٢- متساهل جداً في مواعيد تسليم الواجبات\n\n٣- جداً حقاني في التصحيح ماينقصك ولا يزيدك\n\n٤- كان كوردنيتر الكورس فكلمه طالب عشان يخلي الكورس ( آفرج ) لأنه كان ( ستاندر ) فقال كلمة لطيفة ( أنا أؤمن إن القمة تسع الجميع وليس لواحد فقط )\n\n٥- أوقات الأوفس أور حقته ما كانت تناسبني فكان يستقبلني في أي وقت في مكتبه الثاني في مبنى ١٧ - لأنه مدير مركز التميز للمؤسسات الغير ربحية أو القطاع الثالث-.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524829-math225", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hattan-tawfiq/68372/30", "user": "user11942", "ts": 1597787774000, "tid": 68372, "pn": 30}}]}', 1597787774000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
